  let responseText = 'Hello World!<br>';
  responseText += `<small>Requested at: ${req.requestTime}</small>`;
  res.send(responseText);
});

app.listen(3000);
```

```ts title="index.ts"
import express, { type Express, type Request, type Response, type NextFunction } from 'express';

const app: Express = express();

const requestTime = function (req: Request, res: Response, next: NextFunction) {
  req.requestTime = Date.now();
  next();
};

app.use(requestTime);

app.get('/', (req: Request, res: Response) => {
  let responseText = 'Hello World!<br>';
  responseText += `<small>Requested at: ${req.requestTime}</small>`;
  res.send(responseText);
});

app.listen(3000);
```

Cuando hace una solicitud a la raíz de la aplicación, la aplicación ahora muestra la marca de tiempo de su solicitud en el navegador.

### Función Middleware validateCookies

Finalmente, crearemos una función de middleware que valida las cookies entrantes y envía una respuesta 400 si las cookies no son válidas.

Aquí hay una función de ejemplo que valida las cookies con un servicio externo asíncrono.

```js
async function cookieValidator(cookies) {
  try {
    await externallyValidateCookie(cookies.testCookie);
  } catch {
    throw new Error('Invalid cookies');
  }
}
```

```ts
async function cookieValidator(cookies: Record<string, string>) {
  try {
    await externallyValidateCookie(cookies.testCookie);
  } catch {
    throw new Error('Invalid cookies');
  }
}
```

El middleware `validateCookies` devuelve una Promesa que al rechazar activará automáticamente nuestro gestor de errores. Aquí usamos el [`cookie-parser`](/resources/middleware/cookie-parser) middleware para analizar las cookies entrantes del objeto `req` y pasarlas a nuestra función `cookieValidator`.

```cjs title="index.cjs"
const express = require('express');
const cookieParser = require('cookie-parser');
const cookieValidator = require('./cookieValidator');

const app = express();

async function validateCookies(req, res, next) {
  await cookieValidator(req.cookies);
  next();
}

app.use(cookieParser());

app.use(validateCookies);

// error handler
app.use((err, req, res, next) => {
  res.status(400).send(err.message);
});

app.listen(3000);
```

```mjs title="index.mjs"
import express from 'express';
import cookieParser from 'cookie-parser';
import cookieValidator from './cookieValidator';

const app = express();

async function validateCookies(req, res, next) {
  await cookieValidator(req.cookies);
  next();
}

app.use(cookieParser());

app.use(validateCookies);

// error handler
app.use((err, req, res, next) => {
  res.status(400).send(err.message);
});

app.listen(3000);
```

```ts title="index.ts"
import express, { type Express, type Request, type Response, type NextFunction } from 'express';
import cookieParser from 'cookie-parser';
import cookieValidator from './cookieValidator';

const app: Express = express();

async function validateCookies(req: Request, res: Response, next: NextFunction) {
  await cookieValidator(req.cookies);
  next();
}

app.use(cookieParser());

app.use(validateCookies);

// error handler
app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
  res.status(400).send(err.message);
});

app.listen(3000);
```

<Alert type="alerta">

Observe cómo `next()` es llamado después de `await cookieValidator(req.cookies)`. Esto asegura que si
`cookieValidator` resuelve, se llamará al siguiente middleware en la pila. Si pasas algo
a la función `next()` (excepto la cadena `'route'` o `'router'`), Express considera que la actual petición
es un error y se saltará cualquier función
que no sea de manejo de enrutamiento y middleware restante.

</Alert>

Debido a que tiene acceso al objeto de solicitud, el objeto de respuesta, la siguiente función de middleware en la pila, y el nodo entero. s API, las posibilidades con funciones middleware son infinitas.

Para más información sobre middleware exprés, vea: [Usando middleware exprés](/guide/using-middleware).

## Middleware configurable

Si necesita que su middleware sea configurable, exporte una función que acepte un objeto de opciones u otros parámetros, , que luego devuelve la implementación de middleware basada en los parámetros de entrada.

```cjs title="my-middleware.cjs"
module.exports = function (options) {
  return function (req, res, next) {
    // Implement the middleware function based on the options object
    next();
  };
};
```

```mjs title="my-middleware.mjs"
export default function (options) {
  return function (req, res, next) {
    // Implement the middleware function based on the options object
    next();
  };
}
```

```ts title="my-middleware.ts"
import { type Request, type Response, type NextFunction } from 'express';

export default function (options: Record<string, unknown>) {
  return function (req: Request, res: Response, next: NextFunction) {
    // Implement the middleware function based on the options object
    next();
  };
}
```

El middleware ahora puede ser usado como se muestra a continuación.

```cjs title="index.cjs"
const mw = require('./my-middleware.cjs');

app.use(mw({ option1: '1', option2: '2' }));
```

```mjs title="index.mjs"
import mw from './my-middleware.mjs';

app.use(mw({ option1: '1', option2: '2' }));
```

Consulte [cookie-session](https://github.com/expressjs/cookie-session) y [compression](https://github.com/expressjs/compression) para ver ejemplos de middleware configurable.

