const app: Express = express();
const router = express.Router();

// a middleware function with no mount path. This code is executed for every request to the router
router.use((req: Request, res: Response, next: NextFunction) => {
  console.log('Time:', Date.now());
  next();
});

// a middleware sub-stack shows request info for any type of HTTP request to the /user/:id path
router.use(
  '/user/:id',
  (req: Request, res: Response, next: NextFunction) => {
    console.log('Request URL:', req.originalUrl);
    next();
  },
  (req: Request, res: Response, next: NextFunction) => {
    console.log('Request Type:', req.method);
    next();
  }
);

// a middleware sub-stack that handles GET requests to the /user/:id path
router.get(
  '/user/:id',
  (req: Request, res: Response, next: NextFunction) => {
    // if the user ID is 0, skip to the next router
    if (req.params.id === '0') next('route');
    // otherwise pass control to the next middleware function in this stack
    else next();
  },
  (req: Request, res: Response, next: NextFunction) => {
    // render a regular page
    res.render('regular');
  }
);

// handler for the /user/:id path, which renders a special page
router.get('/user/:id', (req: Request, res: Response, next: NextFunction) => {
  console.log(req.params.id);
  res.render('special');
});

// mount the router on the app
app.use('/', router);
```

Pour sauter le reste des fonctions du middleware du routeur, appelez `next('router')`
pour passer le contrôle hors de l'instance du routeur.

Cet exemple montre une sous-pile middleware qui gère les requêtes GET vers le chemin `/user/:id`.

```cjs title="index.cjs"
const express = require('express');
const app = express();
const router = express.Router();

// predicate the router with a check and bail out when needed
router.use((req, res, next) => {
  if (!req.headers['x-auth']) return next('router');
  next();
});

router.get('/user/:id', (req, res) => {
  res.send('hello, user!');
});

// use the router and 401 anything falling through
app.use('/admin', router, (req, res) => {
  res.sendStatus(401);
});
```

```mjs title="index.mjs"
