    next();
  },
  (req: Request, res: Response, next: NextFunction) => {
    res.send('User Info');
  }
);

// handler for the /user/:id path, which prints the user ID
app.get('/user/:id', (req: Request, res: Response, next: NextFunction) => {
  res.send(req.params.id);
});
```

Pour sauter le reste des fonctions du middleware à partir d'une pile de middleware du routeur, appelez `next('route')` pour passer le contrôle à la route suivante.

<Alert type="Infos">

`next('route')` ne fonctionnera que dans les fonctions du middleware qui ont été chargées en utilisant les fonctions
`app.METHOD()` ou `router.METHOD()`.

</Alert>

Cet exemple montre une sous-pile middleware qui gère les requêtes GET vers le chemin `/user/:id`.

```js
app.get(
  '/user/:id',
  (req, res, next) => {
    // if the user ID is 0, skip to the next route
    if (req.params.id === '0') next('route');
    // otherwise pass the control to the next middleware function in this stack
    else next();
  },
  (req, res, next) => {
    // send a regular response
    res.send('regular');
  }
);

// handler for the /user/:id path, which sends a special response
app.get('/user/:id', (req, res, next) => {
  res.send('special');
});
```

