#### `package.json`

El archivo `package.json` de la versión 3 que acompaña podría verse
algo así:

```json
{
  "name": "application-name",
  "version": "0.0.1",
  "private": true,
  "scripts": {
    "start": "node app.js"
  },
  "dependencies": {
    "express": "3.12.0",
    "pug": "*"
  }
}
```

### Proceso

Comience el proceso de migración instalando el middleware necesario para la aplicación
Express 4 y actualizando Express y Pug a su respectiva versión
con el siguiente comando:

<PackageManagerCommand command="npm install serve-favicon morgan method-override express-session body-parser multer errorhandler express@latest pug@latest --save" />

Hacer los siguientes cambios a `app.js`:

1. El middleware Express incorporado funciona `express.favicon`,
   `express.logger`, `express.methodOverride`,
   `express.session`, `express.bodyParser` y
   `express.errorHandler` ya no están disponibles en el objeto
   `express`. Debes instalar sus alternativas
   manualmente y cargarlas en la aplicación.

2. Ya no necesitas cargar la función `app.router`.
   No es un objeto de aplicación Express 4 válido, por lo que elimina el código
   `app.use(app.router);`.

3. Asegúrese de que las funciones de middleware se cargan en el orden correcto - cargar `errorHandler` después de cargar las rutas de la aplicación.

### Versión 4 app

#### `package.json`

Ejecutar el comando anterior `npm` actualizará `package.json` de la siguiente manera:

```json
{
  "name": "application-name",
  "version": "0.0.1",
  "private": true,
  "scripts": {
    "start": "node app.js"
  },
  "dependencies": {
    "body-parser": "^1.5.2",
    "errorhandler": "^1.1.1",
    "express": "^4.8.0",
    "express-session": "^1.7.2",
    "pug": "^2.0.0",
    "method-override": "^2.1.2",
    "morgan": "^1.2.2",
    "multer": "^0.1.3",
    "serve-favicon": "^2.0.1"
  }
}
```

#### `app.js`

Luego, elimina el código inválido, carga el middleware necesario y haz otros cambiosformat@@0
según sea necesario. El archivo `app.js` se verá así:

```cjs title="index.cjs"
var http = require('http');
var express = require('express');
var routes = require('./routes');
var user = require('./routes/user');
var path = require('path');

var favicon = require('serve-favicon');
var logger = require('morgan');
var methodOverride = require('method-override');
var session = require('express-session');
var bodyParser = require('body-parser');
var multer = require('multer');
var errorHandler = require('errorhandler');

var app = express();

// all environments
app.set('port', process.env.PORT || 3000);
app.set('views', path.join(__dirname, 'views'));
app.set('view engine', 'pug');
app.use(favicon(path.join(__dirname, '/public/favicon.ico')));
app.use(logger('dev'));
app.use(methodOverride());
app.use(
  session({
    resave: true,
    saveUninitialized: true,
    secret: 'uwotm8',
  })
);
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.use(multer());
app.use(express.static(path.join(__dirname, 'public')));

app.get('/', routes.index);
app.get('/users', user.list);

// error handling middleware should be loaded after the loading the routes
if (app.get('env') === 'development') {
  app.use(errorHandler());
}

var server = http.createServer(app);
server.listen(app.get('port'), () => {
  console.log('Express server listening on port ' + app.get('port'));
});
```

```mjs title="index.mjs"
import http from 'http';
import express from 'express';
import routes from './routes';
import user from './routes/user';
import path from 'path';
import favicon from 'serve-favicon';
import logger from 'morgan';
import methodOverride from 'method-override';
import session from 'express-session';
import bodyParser from 'body-parser';
import multer from 'multer';
import errorHandler from 'errorhandler';

const app = express();

// all environments
app.set('port', process.env.PORT || 3000);
app.set('views', path.join(__dirname, 'views'));
app.set('view engine', 'pug');
app.use(favicon(path.join(__dirname, '/public/favicon.ico')));
app.use(logger('dev'));
app.use(methodOverride());
app.use(
  session({
    resave: true,
    saveUninitialized: true,
    secret: 'uwotm8',
  })
);
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.use(multer());
app.use(express.static(path.join(__dirname, 'public')));

app.get('/', routes.index);
app.get('/users', user.list);

// error handling middleware should be loaded after the loading the routes
if (app.get('env') === 'development') {
  app.use(errorHandler());
}

const server = http.createServer(app);
server.listen(app.get('port'), () => {
  console.log('Express server listening on port ' + app.get('port'));
});
```

<Alert type="info">
A menos que necesite trabajar directamente con el módulo `http` (socket.io/SPDY/HTTPS), cargarlo no es necesario, y la aplicación puede iniciarse simplemente de esta manera:

```js
app.listen(app.get('port'), () => {
  console.log('Express server listening on port ' + app.get('port'));
});
```

</Alert>

### Ejecutar la aplicación

El proceso de migración se ha completado, y la aplicación es ahora una aplicación
Express 4. Para confirmar, inicia la aplicación usando el siguiente comando:

```bash
$ node .
```

Cargar [http://localhost:3000](http://localhost:3000)
y ver la página de inicio mostrada por Express 4.

## Actualización al generador de aplicaciones Express 4

La herramienta de línea de comandos para generar una aplicación Express sigue siendo
`express`, pero para actualizar a la nueva versión, debe desinstalar
el generador de aplicaciones Express 3 y luego instalar el nuevo generador
`express-generator`.

### Instalando

Si ya tiene instalado el generador de aplicaciones Express 3 en su sistema,
debe desinstalarlo:

<PackageManagerCommand command="npm uninstall -g express" />

Dependiendo de cómo estén configurados tus privilegios de archivo y directorio,
puede que necesites ejecutar este comando con `sudo`.

Ahora instale el nuevo generador:

<PackageManagerCommand command="npm install -g express-generator" />

Dependiendo de cómo estén configurados tus privilegios de archivo y directorio,
puede que necesites ejecutar este comando con `sudo`.

Ahora el comando `express` en su sistema se actualiza al generador
Express 4.

### Cambios al generador de aplicaciones

Las opciones de comando y uso siguen siendo en gran medida las mismas, con las siguientes excepciones:

- Se ha eliminado la opción `--sessions`.
- Se ha eliminado la opción `--jshtml`.
- Se añadió la opción `--hogan` para soportar [Hogan.js](http://twitter.github.io/hogan.js/).

### Ejemplo

Ejecutar el siguiente comando para crear una aplicación Express 4:

```bash
$ express app4
```

Si observas el contenido del archivo `app4/app.js`, notarás
que todas las funciones de middleware (excepto `express. tatic`) que son requeridos para
la aplicación se cargan como módulos independientes, y el middleware `router`
ya no se carga explícitamente en la aplicación.

También notará que el archivo `app.js` es ahora un Nodo. , en contraste con la aplicación independiente generada por el generador anterior.

Después de instalar las dependencias, inicie la aplicación usando el siguiente comando:

```bash
$ npm start
```

Si miras el script `npm start` en el `paquete. archivo son`,
notarás que el comando real que inicia la aplicación es
`node . bin/www`, que solía ser `node app.js`
en Express 3.

Porque el archivo `app.js` que fue generado por el generador Express 4
es ahora un Nodo. s módulo, ya no puede iniciarse independientemente como una aplicación
(a menos que modifiques el código). El módulo debe cargarse en un archivo Node.js
y debe iniciarse a través del archivo Node.js. El archivo Node.js es `./bin/www`
en este caso.

Ni el directorio `bin` ni el archivo sin extensión `www`
es obligatorio para crear una aplicación Express o iniciar la aplicación. Son
solo sugerencias hechas por el generador, así que siéntete libre de modificarlas para adaptarse a tus
necesidades.

Para deshacerse del directorio `www` y mantener las cosas de la forma "Express 3",
borrar la línea que dice `module. xports = app;` al final del archivo
`app.js`, luego pega el siguiente código en su lugar:

```js
app.set('port', process.env.PORT || 3000);

var server = app.listen(app.get('port'), () => {
  debug('Express server listening on port ' + server.address().port);
});
```

Asegúrese de cargar el módulo `debug` en la parte superior del archivo `app.js` usando el siguiente código:

```js
var debug = require('debug')('app4');
```

A continuación, cambia `"start": "node ./bin/www"` en el archivo `package.json` a `"start": "node app.js"`.

Ahora ha movido la funcionalidad de `./bin/www` de vuelta a
`app.js`. Este cambio no es recomendable, pero el ejercicio te ayuda
a entender cómo el `. bin/www` archivo funciona, y por qué el archivo `app.js`
ya no comienza por sí mismo.

---
title: Actualizar a Express v5
description: Una guía completa para migrar sus aplicaciones Express.js de la versión 4 a 5, detallando los cambios de ruptura, métodos obsoletos y nuevas mejoras.
---

import Alert from '@components/primitives/Alert/Alert.astro';
import PackageManagerCommand from '@components/patterns/PackageManagerCommand/PackageManagerCommand.astro';

Express 5 no es muy diferente de Express 4; aunque mantiene la misma API básica, todavía hay cambios que rompen la compatibilidad con la versión anterior. Por lo tanto, una aplicación construida con Express 4 podría no funcionar si la actualiza para usar Express 5.

## Instalación

Para instalar esta versión, necesitas tener una **versión 18 o superior de Node.js**. Luego, ejecuta el siguiente comando en el directorio de tu aplicación:

<PackageManagerCommand command="npm install &#x22;express@5&#x22;" />

Luego puede ejecutar sus pruebas automatizadas para ver qué falla, y arreglar problemas de acuerdo a las actualizaciones que se listan a continuación. Después de gestionar los fallos de prueba, ejecuta tu aplicación para ver qué errores ocurren. Descubrirá de inmediato si la aplicación utiliza cualquier método o propiedades que no sean compatibles.

## Códigos Express 5

Para ayudarle a migrar su servidor exprés, hemos creado un conjunto de códigos que te ayudarán a actualizar automáticamente tu código a la última versión de Express.

Ejecutar el siguiente comando para ejecutar todos los codemods disponibles:

<PackageManagerCommand command="npx codemod@latest @expressjs/v5-migration-recipe" />

Si quieres ejecutar un código específico, puedes ejecutar el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/name-of-the-codemod" />

Puedes encontrar la lista de códigos disponibles [here](https://codemod.link/express).

## Métodos y propiedades eliminados

Si utiliza cualquiera de estos métodos o propiedades en su aplicación, se bloqueará. Por lo tanto, necesitarás cambiar tu aplicación después de actualizar a la versión 5.

### app.del()

Express 5 ya no soporta la función `app.del()`. Si utiliza esta función, se arroja un error. Para registrar rutas HTTP DELETE, utilice la función `app.delete()` en su lugar.

Inicialmente, `del` fue usado en lugar de `delete`, porque `delete` es una palabra clave reservada en JavaScript. Sin embargo, a partir de ECMAScript 6, `delete` y otras palabras clave reservadas pueden utilizarse legalmente como nombres de propiedad.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/route-del-to-delete" />

O puedes actualizar tu código manualmente:

```diff
-app.del('/user/:id', (req, res) => {
+app.delete('/user/:id', (req, res) => {
   res.send(`DELETE /user/${req.params.id}`);
 });
```

### app.param(fn)

La firma `app.param(fn)` fue usada para modificar el comportamiento de la función `app.param(name, fn)`. Ha sido obsoleto desde v4.11.0, y Express 5 ya no lo soporta en absoluto.

### Nombres de métodos pluralizados

Los siguientes nombres de métodos han sido pluralizados. En Express 4, el uso de los métodos antiguos resultó en una advertencia de desaprobación. Express 5 ya no los soporta:

`req.acceptsCharset()` es reemplazado por `req.acceptsCharsets()`.

`req.acceptsEncoding()` es reemplazado por `req.acceptsEncodings()`.

`req.acceptsLanguage()` es reemplazado por `req.acceptsLanguages()`.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/pluralize-method-names" />

O puedes actualizar tu código manualmente:

```diff
 app.all('/', (req, res) => {
-  req.acceptsCharset('utf-8');
-  req.acceptsEncoding('br');
-  req.acceptsLanguage('en');
+  req.acceptsCharsets('utf-8');
+  req.acceptsEncodings('br');
+  req.acceptsLanguages('en');

   // ...
 });
```

### Posible coma (:) en el nombre de app.param(nombre, fn)

Un personaje con dos puntos (:) en el nombre de la aplicación `. aram(name, fn)` función es un remanente de Express 3, y por el bien de la compatibilidad hacia atrás, Express 4 lo soportó con un aviso de desaprobación. Express 5 lo ignorará silenciosamente y usará el parámetro de nombre sin prefijarlo con dos puntos.

This should not affect your code if you follow the Express 4 documentation of [app.param](/4x/api/application/#appparam), as it makes no mention of the leading colon.

### req.param(nombre)

Se ha eliminado este método potencialmente confuso y peligroso de recuperar datos de formularios. Ahora necesitará buscar específicamente el nombre del parámetro enviado en el objeto `req.params`, `req.body`, o `req.query`.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/explicit-request-params" />

O puedes actualizar tu código manualmente:

```diff
 app.post('/user', (req, res) => {
-  const id = req.param('id');
-  const body = req.param('body');
-  const query = req.param('query');
+  const id = req.params.id;
+  const body = req.body;
+  const query = req.query;

   // ...
 });
```

### res.json(obj, estado)

Express 5 ya no soporta la firma `res.json(obj, status)`. En su lugar, establece el estado y luego lo encadena al método `res.json()` de esta manera: `res.status(status).json(obj)`.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/status-send-order" />

O puedes actualizar tu código manualmente:

```diff
 app.post('/user', (req, res) => {
-  res.json({ name: 'Ruben' }, 201);
+  res.status(201).json({ name: 'Ruben' });
 });
```

### res.jsonp(obj, status)

Express 5 ya no soporta la firma `res.jsonp(obj, status)`. En su lugar, establece el estado y luego lo encadena al método `res.jsonp()` de esta manera: `res.status(status).jsonp(obj)`.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/status-send-order" />

O puedes actualizar tu código manualmente:

```diff
 app.post('/user', (req, res) => {
-  res.jsonp({ name: 'Ruben' }, 201);
+  res.status(201).jsonp({ name: 'Ruben' });
 });
```

### res.redirect(url, status)

Express 5 ya no soporta la firma `res.redirect(url, status)`. En su lugar, utilice la siguiente firma: `res.redirect(status, url)`.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/redirect-arg-order" />

O puedes actualizar tu código manualmente:

```diff
 app.get('/user', (req, res) => {
-  res.redirect('/users', 302);
+  res.redirect(302, '/users');
 });

 // A redirect that relies on the default 302 status is unaffected
 app.get('/admin', (req, res) => {
   res.redirect('/dashboard');
 });
```

### res.redirect('back') y res.location('back')

Express 5 ya no soporta la cadena mágica `back` en los métodos `res.redirect()` y `res.location()`. En su lugar, utilice el valor `req.get('Referrer') || '/'` para redirigir de vuelta a la página anterior. En Express 4, los métodos `res.redirect('back')` y `res.location('back')` fueron obsoletos.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/back-redirect-deprecated" />

O puedes actualizar tu código manualmente:

```diff
 app.get('/user', (req, res) => {
-  res.redirect('back');
+  res.redirect(req.get('Referrer') || '/');
 });
```

### res.send(cuerpo, estado)

Express 5 ya no soporta la firma `res.send(obj, status)`. En su lugar, establece el estado y luego lo encadena al método `res.send()` de esta manera: `res.status(status).send(obj)`.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/status-send-order" />

O puedes actualizar tu código manualmente:

```diff
 app.get('/user', (req, res) => {
-  res.send({ name: 'Ruben' }, 200);
+  res.status(200).send({ name: 'Ruben' });
 });
```

### res.send(status)

Express 5 ya no soporta la firma `res.send(status)`, donde `status` es un número. En su lugar, use el `res. función endStatus(statusCode)`, que establece el código de estado de la cabecera de respuesta HTTP y envía la versión de texto del código: "No encontrado", "Error interno del servidor", y así sucesivamente.
Si necesita enviar un número usando el `res. función end()`, cita el número para convertirlo en una cadena, para que Express no lo interprete como un intento de usar la antigua firma no soportada.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/status-send-order" />

O puedes actualizar tu código manualmente:

```diff
 app.get('/user', (req, res) => {
-  res.send(200);
+  res.sendStatus(200);
 });
```

### res.sendfile()

La función `res.sendfile()` ha sido reemplazada por una versión `res.sendFile()` con casilla de camellos en Express 5.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/camelcase-sendfile" />

O puedes actualizar tu código manualmente:

```diff
 app.get('/user', (req, res) => {
-  res.sendfile('/path/to/file');
+  res.sendFile('/path/to/file');
 });
```

### opciones res.sendFile()

Las opciones `hidden` y `from` para `res.sendFile()` ya no son compatibles. En su lugar, usa `dotfiles` y `root`.

The `dotfiles` option applies to hidden directories in the path as well as hidden files. For example, a file served from an absolute path like `/var/www/app/.cache/index.html` now requires `dotfiles: 'allow'`, even though `index.html` is not a dotfile. In Express 4 a hidden directory in the path was served by default; Express 5 returns `404` unless you opt in.

This check only applies to the part of the path that `send` evaluates. When you pass a `root`, only the portion relative to `root` is checked, so a hidden directory inside `root` is unaffected.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/sendfile-options" />

O puedes actualizar tu código manualmente:

```diff
 app.get('/files/:name', (req, res) => {
-  res.sendFile(req.params.name, { hidden: true, from: '/uploads' });
+  res.sendFile(req.params.name, { dotfiles: 'allow', root: '/uploads' });
 });
```

If you serve an absolute path that contains a hidden directory, opt in with `dotfiles: 'allow'` or use `root` so the hidden segment is not part of the evaluated path:

```diff
 app.get('/build', (req, res) => {
-  res.sendFile('/var/www/app/.cache/index.html');
+  res.sendFile('/var/www/app/.cache/index.html', { dotfiles: 'allow' });
+  // or: res.sendFile('index.html', { root: '/var/www/app/.cache' });
 });
```

### opciones express.static()

Las opciones `hidden` y `from` para `express.static()` ya no están soportadas. En su lugar, usa `dotfiles` y `root`. Ten en cuenta que `from` nunca fue documentado en la API pero fue aceptado como un alias para `root`. El valor por defecto de `dotfiles` ahora es `"ignore"`.

The `dotfiles` check now also applies to hidden **directories** in the request path, not just hidden files. A request like `GET /.well-known/acme-challenge/...` that was served by default in Express 4 now returns `404` unless you set `dotfiles: 'allow'`. This only affects the part of the path relative to the configured `root`; a hidden directory in `root` itself is unaffected.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/static-dotfiles" />

O puedes actualizar tu código manualmente:

```diff
 const express = require('express');
 const app = express();

-app.use(express.static('public', { hidden: true }));
+app.use(express.static('public', { dotfiles: 'allow' }));
```

If you rely on serving a hidden directory such as `.well-known` (for example, ACME/Let's Encrypt challenges), opt in explicitly. This is needed even if you never used the `hidden` option:

```diff
-app.use(express.static('public'));
+app.use(express.static('public', { dotfiles: 'allow' }));
```

### router.param(fn)

La firma `router.param(fn)` fue usada para modificar el comportamiento de la función `router.param(name, fn)`. Ha sido obsoleto desde v4.11.0, y Express 5 ya no lo soporta en absoluto.

### express.static.mime

En Express 5, `mime` ya no es una propiedad exportada del campo `static`.
Usa el [`mime-types` paquete](https://github.com/jshttp/mime-types) para trabajar con valores de tipo MIME.

#### Cómo actualizar

Puedes actualizar automáticamente tu código ejecutando el siguiente comando:

<PackageManagerCommand command="npx codemod@latest @expressjs/static-mime" />

O puedes actualizar tu código manualmente:

```diff
-express.static.mime.lookup('json');
+const mime = require('mime-types');
+mime.lookup('json');
```

### Cambios de tipo MIME

Varios tipos de MIME han cambiado debido a actualizaciones en [`mime-db`](https://github.com/jshttp/mime-db). Estos cambios sólo afectan a `express.static()` y `res.sendFile()`. Para una lista completa de cambios, vea el [`mime-db` changelog](https://github.com/jshttp/mime-db/blob/HEAD/HISTORY.md).

Express 4 utiliza la versión `mime-db` **1.52.0**, mientras que Express 5 utiliza versiones más recientes que reflejan las actualizaciones a las especificaciones de tipo IANA y otras MIME. El cambio más notable es que los archivos JavaScript (`.js`) ahora se sirven como `text/javascript` en lugar de `application/javascript`.

En Express 5, los cambios a los tipos MIME de las actualizaciones `mime-db` no se consideran como romper los cambios, así que tenga cuidado al actualizar sus dependencias ya que los tipos MIME pueden cambiar entre versiones menores o parches.

### express:router debug logs

La lógica de manejo del enrutador ahora es realizada por una dependencia separada ([`router`](https://github.com/pillarjs/router)) mantenida por el equipo Express, por lo que los registros de depuración se han movido a un espacio de nombres diferente. Antes de Express 5.1, estos registros de depuración no existían. Para obtenerlos, actualiza a una versión reciente de Express 5 o actualiza el paquete `router` en tu `package-lock.json`:

| v4                          | v5                                  |
| --------------------------- | ----------------------------------- |
| `express:router`            | `router`                            |
| `express:router:layer`      | `router:layer`                      |
| `express:router:route`      | `router:route`                      |
| `express:*` (incluye todos) | `express:*` + `router` + `router:*` |

#### Cómo actualizar

```diff
-DEBUG=express:* node index.js
+DEBUG=express:*,router,router:* node index.js
```

## Cambiado

Estas APIs todavía existen, pero su comportamiento ha cambiado. Revise estos cambios para asegurarse de que su aplicación funciona como se esperaba.

### Ruta de ruta que coincide con sintaxis

Ruta de ruta que coincide con la sintaxis es cuando se proporciona una cadena como el primer parámetro a las APIs `app.all()`, `app.use()`, `app.METHOD()`, `router.all()`, `router.METHOD()`, y `router.use()`. Se han realizado los siguientes cambios en cómo la cadena de ruta se corresponde con una solicitud entrante:

- El comodín `*` debe tener un nombre, coincidiendo con el comportamiento de los parámetros `:`, use `/*splat` en lugar de `/*`

  ```diff
  -app.get('/*', async (req, res) => {
  +app.get('/*splat', async (req, res) => {
     res.send('ok');
   });
  ```

  <Alert type="info">

  `*splat` coincide con cualquier ruta sin la ruta raíz. Si necesita coincidir con la ruta de la raíz también `/`, puede usar `/{*splat}`, envolviendo el comodín entre llaves.

  ```js
  app.get('/{*splat}', async (req, res) => {
    res.send('ok');
  });
  ```

  </Alert>

- El carácter opcional `?` ya no es compatible, utilice llaves en su lugar.

  ```diff
  -app.get('/:file.:ext?', async (req, res) => {
  +app.get('/:file{.:ext}', async (req, res) => {
     res.send('ok');
   });
  ```

- Los caracteres de expresión regular no son compatibles. Por ejemplo:

  ```diff
  -app.get('/[discussion|page]/:slug', async (req, res) => {
  +app.get(['/discussion/:slug', '/page/:slug'], async (req, res) => {
     res.status(200).send('ok');
   });
  ```

- Algunos caracteres han sido reservados para evitar confusión durante la actualización (`()[]?+!`), use `\` para escapar de ellos.

- Los nombres de parámetros ahora soportan identificadores JavaScript válidos, o citan como `:"this"`.

### Las promesas rechazadas manejadas por middleware y manejadores

Solicitar middleware y manejadores que devuelven promesas rechazadas ahora son manejados reenviando el valor rechazado como un `Error` al middleware que maneja errores. Esto significa que usar 'async' funciones como middleware y manejadores son más fáciles que nunca. Cuando se arroja un error en una función `async` o una promesa rechazada es `await`ed dentro de una función asíncrona, esos errores se pasarán al gestor de errores como si llamara a `next(err)`.

Detalles de cómo Express maneja los errores se cubren en la [documentación de manejo de errores](/guide/error-handling).

#### Cómo actualizar

Ahora puedes usar `async/await` directamente sin captar errores manualmente. Si `getUserById` arroja un error o rechaza, `next` será llamado automáticamente con el valor rechazado.

```diff
-app.get('/user/:id', (req, res, next) => {
-  getUserById(req.params.id)
-    .then((user) => res.send(user))
-    .catch(next);
-});
+app.get('/user/:id', async (req, res) => {
+  const user = await getUserById(req.params.id);
+  res.send(user);
+});
```

### express.urlencoded

El método `express.urlencoded` hace que la opción `extended` sea `false` por defecto.

#### Cómo actualizar

Si tu aplicación se basa en el comportamiento `extended`, explícitamente establecerlo a `true`:

```diff
-app.use(express.urlencoded());
+app.use(express.urlencoded({ extended: true }));
```

### express.static dotfiles

La opción `dotfiles` de `express.static` de middleware ahora es `"ignore"`. En Express 4, los archivos de puntos fueron servidos por defecto. Como resultado, archivos dentro de un directorio que comienza con un punto (`.`), como `. ell-known`, ya no será accesible y devolverá un error **404 No encontrado**. Esto puede romper la funcionalidad que depende de servir directorios de puntos, como Android App Links y Apple Universal Links.

#### Cómo actualizar

Serve directorios de puntos específicos usando explícitamente `dotfiles: opción "allow"`. Esto le permite servir de forma segura sólo los directorios de puntos deseados mientras mantiene el comportamiento seguro por defecto para otros ficheros de puntos.

```diff
+app.use('/.well-known', express.static('public/.well-known', { dotfiles: 'allow' }));
 app.use(express.static('public'));
```

### router.param() with an array of names

`router.param(name, fn)` no longer accepts an array for `name`. In Express 4 an array was accepted silently; in Express 5, passing anything other than a string throws `TypeError: argument name must be a string`. (Note that `app.param()` still accepts an array of names.)

#### Cómo actualizar

Register each parameter name with its own `router.param()` call:

```diff
-router.param(['id', 'page'], (req, res, next, value) => {
-  // ...
-});
+const loadParam = (req, res, next, value) => {
+  // ...
+};
+router.param('id', loadParam);
+router.param('page', loadParam);
```

### app.listen

En Express 5, el método `app.listen` invocará la función callback proporcionada por el usuario (si se proporciona) cuando el servidor reciba un evento de error. En Express 4, esos errores se lanzarían. This change shifts error handling responsibility to the callback function in Express 5. Si hay un error, se pasará al callback como argumento.
Por ejemplo:

```js ins={2-4}
const server = app.listen(8080, '0.0.0.0', (error) => {
  if (error) {
    throw error; // e.g. EADDRINUSE
  }
  console.log(`Listening on ${JSON.stringify(server.address())}`);
});
```

### app.router

El objeto `app.router`, que fue eliminado en Express 4, ha regresado en Express 5. En la nueva versión, este objeto es sólo una referencia al router base Express, a diferencia de en Express 3, donde una aplicación tuvo que cargarla explícitamente.

### req.body

La propiedad `req.body` devuelve `undefined` cuando el cuerpo no ha sido analizado. En Express 4, devuelve `{}` por defecto.

```js del={4} ins={6}
app.post('/user', (req, res) => {
  console.dir(req.body);
  // Express 4
  // => {}
  // Express 5
  // => undefined
});
```

### req.host

En Express 4, la función `req.host` borró incorrectamente del número de puerto si estaba presente. En Express 5, el número de puerto se mantiene.

### req.params

El objeto `req.params` ahora tiene un **prototipo nulo** al usar rutas de cadenas. Sin embargo, si la ruta se define con una expresión regular, `req.params` sigue siendo un objeto estándar con un prototipo normal. Además, hay dos cambios de comportamiento importantes:

**Los parámetros comodín ahora son arrays:**

Los comodines (por ejemplo, `/*splat`) capturan segmentos de ruta como una matriz en lugar de una sola cadena.

```js
app.get('/*splat', (req, res) => {
  // GET /foo/bar
  console.dir(req.params);
  // => [Object: null prototype] { splat: [ 'foo', 'bar' ] }
});
```

**Parámetros no coincidentes son omitidos:**

En Express 4, los comodines no coinciden eran cadenas vacías (`''`) y los parámetros opcionales `:` (usando `?`) tenían una clave con valor `undefined`. En Express 5, los parámetros no coincidentes se omiten completamente de `req.params`.

```diff
-// v4: unmatched wildcard is empty string
-app.get('/*', (req, res) => {
-  // GET /
-  console.dir(req.params);
-  // => { '0': '' }
-});
-
-// v4: unmatched optional param is undefined
-app.get('/:file.:ext?', (req, res) => {
-  // GET /image
-  console.dir(req.params);
-  // => { file: 'image', ext: undefined }
-});
-
+// v5: unmatched optional param is omitted
+app.get('/:file{.:ext}', (req, res) => {
+  // GET /image
+  console.dir(req.params);
+  // => [Object: null prototype] { file: 'image' }
+});
```

### req.query

La propiedad `req.query` ya no es una propiedad escribible y en su lugar es un getter. El analizador de consultas por defecto ha sido cambiado de "extendido" a "simple".

```js del={3}
app.get('/search', (req, res) => {
  // This is no longer possible in Express 5
  req.query.page = 1;
});
```

### res.clearCookie

El método `res.clearCookie` ignora las opciones `maxAge` y `expires` proporcionadas por el usuario.

```diff
 app.get('/logout', (req, res) => {
-  res.clearCookie('session', { maxAge: 0, expires: new Date(0) });
+  res.clearCookie('session');
 });
```

### res.estado

El método `res.status` sólo acepta enteros en el rango de `100` a `999`, siguiendo el comportamiento definido por Node. , y devuelve un error cuando el código de estado no es un entero.

```js del={2}
app.get('/user', (req, res) => {
  res.status(99); // Throws an error
  res.status(200); // OK
});
```

### res.variar

El `res.vary` arroja un error cuando falta el argumento `field`. En Express 4, si el argumento fue omitido, dio una advertencia en la consola.

```js del={2}
app.get('/user', (req, res) => {
  res.vary(); // Throws an error
  res.vary('Accept'); // OK
});
```

