app.use(express.logger('dev'));
app.use(express.methodOverride());
app.use(express.session({ secret: 'your secret here' }));
app.use(express.bodyParser());
app.use(app.router);
app.use(express.static(path.join(__dirname, 'public')));

// development only
if (app.get('env') === 'development') {
  app.use(express.errorHandler());
}

app.get('/', routes.index);
app.get('/users', user.list);

http.createServer(app).listen(app.get('port'), () => {
  console.log('Express server listening on port ' + app.get('port'));
});
```

#### `package.json`

Il file `package.json` che accompagna la versione 3 potrebbe sembrare
qualcosa del genere:

```json
{
  "name": "application-name",
  "version": "0.0.1",
  "private": true,
  "scripts": {
    "start": "node app.js"
  },
  "dependencies": {
    "express": "3.12.0",
    "pug": "*"
  }
}
```

### Processo

Inizia il processo di migrazione installando il middleware richiesto per l'app
Express 4 e aggiornando Express e Pug alla rispettiva versione
con il seguente comando:

<PackageManagerCommand command="npm install serve-favicon morgan method-override express-session body-parser multer errorhandler express@latest pug@latest --save" />

Effettuare le seguenti modifiche a `app.js`:

1. The built-in Express middleware functions `express.favicon`,
   `express.logger`, `express.methodOverride`,
   `express.session`, `express.bodyParser` and
   `express.errorHandler` are no longer available on the
   `express` object. Devi installare manualmente le loro alternative
   e caricarle nell'app.

2. Non è più necessario caricare la funzione `app.router`.
   Non è un valido oggetto app Express 4, quindi rimuovi il codice
   `app.use(app.router);`.

3. Assicurati che le funzioni middleware siano caricate nell'ordine corretto: carica `errorHandler` dopo aver caricato le rotte dell'app.

### Versione 4 app

#### `package.json`

L'esecuzione del comando `npm` sopra aggiornerà `package.json` come segue:

```json
{
  "name": "application-name",
  "version": "0.0.1",
  "private": true,
  "scripts": {
    "start": "node app.js"
  },
  "dependencies": {
    "body-parser": "^1.5.2",
    "errorhandler": "^1.1.1",
    "express": "^4.8.0",
    "express-session": "^1.7.2",
    "pug": "^2.0.0",
    "method-override": "^2.1.2",
    "morgan": "^1.2.2",
    "multer": "^0.1.3",
    "serve-favicon": "^2.0.1"
  }
}
```

#### `app.js`

Quindi, rimuovere il codice non valido, caricare il middleware richiesto e fare altre modifiche
se necessario. Il file `app.js` sarà simile a questo:

```cjs title="index.cjs"
var http = require('http');
var express = require('express');
var routes = require('./routes');
var user = require('./routes/user');
var path = require('path');

var favicon = require('serve-favicon');
var logger = require('morgan');
var methodOverride = require('method-override');
var session = require('express-session');
var bodyParser = require('body-parser');
var multer = require('multer');
var errorHandler = require('errorhandler');

var app = express();

// all environments
app.set('port', process.env.PORT || 3000);
app.set('views', path.join(__dirname, 'views'));
app.set('view engine', 'pug');
app.use(favicon(path.join(__dirname, '/public/favicon.ico')));
app.use(logger('dev'));
app.use(methodOverride());
app.use(
  session({
    resave: true,
    saveUninitialized: true,
    secret: 'uwotm8',
  })
);
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.use(multer());
app.use(express.static(path.join(__dirname, 'public')));

app.get('/', routes.index);
app.get('/users', user.list);

// error handling middleware should be loaded after the loading the routes
if (app.get('env') === 'development') {
  app.use(errorHandler());
}

var server = http.createServer(app);
server.listen(app.get('port'), () => {
  console.log('Express server listening on port ' + app.get('port'));
});
```

```mjs title="index.mjs"
import http from 'http';
import express from 'express';
import routes from './routes';
import user from './routes/user';
import path from 'path';
import favicon from 'serve-favicon';
import logger from 'morgan';
import methodOverride from 'method-override';
import session from 'express-session';
import bodyParser from 'body-parser';
import multer from 'multer';
import errorHandler from 'errorhandler';

const app = express();

// all environments
app.set('port', process.env.PORT || 3000);
app.set('views', path.join(__dirname, 'views'));
app.set('view engine', 'pug');
app.use(favicon(path.join(__dirname, '/public/favicon.ico')));
app.use(logger('dev'));
app.use(methodOverride());
app.use(
  session({
    resave: true,
    saveUninitialized: true,
    secret: 'uwotm8',
  })
);
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.use(multer());
app.use(express.static(path.join(__dirname, 'public')));

app.get('/', routes.index);
app.get('/users', user.list);

// error handling middleware should be loaded after the loading the routes
if (app.get('env') === 'development') {
  app.use(errorHandler());
}

const server = http.createServer(app);
server.listen(app.get('port'), () => {
  console.log('Express server listening on port ' + app.get('port'));
});
```

<Alert type="info">
A meno che non sia necessario lavorare direttamente con il modulo `http` (socket.io/SPDY/HTTPS), il caricamento non è richiesto e l'applicazione può essere semplicemente avviata in questo modo:

```js
app.listen(app.get('port'), () => {
  console.log('Express server listening on port ' + app.get('port'));
});
```

</Alert>

### Esegui l'app

Il processo di migrazione è completo, e l'app è ora un'app
Express 4. Per confermare, avviare l'applicazione utilizzando il seguente comando:

```bash
$ node .
```

Carica [http://localhost:3000](http://localhost:3000)
e vedi che la home page è resa da Express 4.

## Aggiornamento al generatore di app Express 4

The command-line tool to generate an Express app is still
`express`, but to upgrade to the new version, you must uninstall
the Express 3 app generator and then install the new
`express-generator`.

### Installazione

Se hai già installato il generatore di app Express 3 sul tuo sistema,
devi disinstallarlo:

<PackageManagerCommand command="npm uninstall -g express" />

A seconda di come i privilegi di file e directory sono configurati,
potrebbe essere necessario eseguire questo comando con `sudo`.

Ora installa il nuovo generatore:

<PackageManagerCommand command="npm install -g express-generator" />

A seconda di come i privilegi di file e directory sono configurati,
potrebbe essere necessario eseguire questo comando con `sudo`.

Ora il comando `express` sul tuo sistema viene aggiornato al generatore
Express 4.

### Modifiche al generatore di app

Le opzioni di comando e l'uso restano in gran parte uguali, con le seguenti eccezioni:

- Rimosso l'opzione `--sessions`.
- Rimosso l'opzione `--jshtml`.
- Aggiunta l'opzione `--hogan` per supportare [Hogan.js](http://twitter.github.io/hogan.js/).

### Esempio

Esegue il seguente comando per creare un'app Express 4:

```bash
$ express app4
```

Se si guarda il contenuto del file `app4/app.js`, si noterà
che tutte le funzioni middleware (tranne `express. tatic`) che sono richiesti per
l'applicazione sono caricati come moduli indipendenti, e il 'router' middleware
non è più esplicitamente caricato nell'app.

Noterai anche che il file `app.js` è ora un Node. s modulo, in contrasto con l'app standalone che è stata generata dal vecchio generatore.

Dopo aver installato le dipendenze, avviare l'applicazione utilizzando il seguente comando:

```bash
$ npm start
```

Se guardi lo script `npm start` nel `package. file son`,
noterai che il comando attuale che avvia l'app è
`node . bin/www`, che era `node app.js`
in Express 3.

Poiché il file `app.js` generato dal generatore di Express 4
è ora un Node. s modulo, non può più essere avviato indipendentemente come app
(a meno che tu non modifichi il codice). Il modulo deve essere caricato in un file Node.js
e avviato tramite il file Node.js. Il file Node.js è `./bin/www`
in questo caso.

Né la directory `bin` né il file `www`
extensionless sono obbligatori per creare un'app Express o per avviare l'app. Sono
solo suggerimenti fatti dal generatore, quindi sentitevi liberi di modificarli per soddisfare le vostre esigenze
.

To get rid of the `www` directory and keep things the "Express 3 way",
delete the line that says `module.exports = app;` at the end of the
`app.js` file, then paste the following code in its place:

```js
app.set('port', process.env.PORT || 3000);

var server = app.listen(app.get('port'), () => {
  debug('Express server listening on port ' + server.address().port);
});
```

Assicurati di caricare il modulo `debug` nella parte superiore del file `app.js` utilizzando il seguente codice:

```js
var debug = require('debug')('app4');
```

Successivamente, cambia `"start": "node ./bin/www"` nel file `package.json` in `"start": "node app.js"`.

Ora hai spostato la funzionalità di `./bin/www` di nuovo in
`app.js`. Questo cambiamento non è raccomandato, ma l'esercizio ti aiuta
a capire come `. bin/www` funziona e perché il file `app.js`
non inizia più da solo.

