const query = N1qlQuery.fromString(n1ql);
bucket.query(query, [13], (err, result) => {
  if (err) {
    console.log(err);
  } else {
    console.log(result);
  }
});
```

## CouchDB

**Module**: [nano](https://github.com/dscape/nano)

### 安装

<PackageManagerCommand command="npm install nano" />

### 示例

```js title="index.js"
const nano = require('nano')('http://localhost:5984');
nano.db.create('books');
const books = nano.db.use('books');

// Insert a book document in the books database
books.insert({ name: 'The Art of war' }, null, (err, body) => {
  if (err) {
    console.log(err);
  } else {
    console.log(body);
  }
});

// Get a list of all books
books.list((err, body) => {
  if (err) {
    console.log(err);
  } else {
    console.log(body.rows);
  }
});
```

## LevelDB

**Module**: [levelup](https://github.com/rvagg/node-levelup)

### 安装

<PackageManagerCommand command="npm install level levelup leveldown" />

### 示例

```cjs title="index.cjs"
const levelup = require('levelup');
const db = levelup('./mydb');

db.put('name', 'LevelUP', (err) => {
  if (err) return console.log('Ooops!', err);

  db.get('name', (err, value) => {
    if (err) return console.log('Ooops!', err);

    console.log(`name=${value}`);
  });
});
```

```mjs title="index.mjs"
